DEFAULT_GRID = (15, 50, 30, 20)

def flips_to_paths(start, flips, forget_orientation=True):
    path = start
    sequence = [path]
    for f in flips:
        path = flip.flip(path, *f, forget_orientation)
        if pl.forget_orientation(path) == pl.forget_orientation(sequence[-1]):
            continue
        
        sequence.append(path)
    return sequence

def solve_and_animate(points, start, target, gif_name="gif-flip-sequence"):
    flips = solver.bfs_solver(points, start, target)
    sequence = flips_to_paths(start, flips)
    animator.create_gif_polyline(DEFAULT_GRID, points, sequence, gif_name)

def random_example(n):
    points = pl.generate_random_points(n)
    start = pl.generate_random_polyline(points, shuffle_points=True)
    target = pl.generate_random_polyline(points)

    print("Randomly generated Reconfiguration problem:")
    print(f"points: {[(round(x,2), round(y,2)) for x,y in points]}")
    print(f"start: {start}")
    print(f"target: {target}")
    animator.draw_polyline(DEFAULT_GRID, points, start, "svg-start-polyline.svg")
    animator.draw_polyline(DEFAULT_GRID, points, target, "svg-target-polyline.svg")
    solve_and_animate(points, start, target)

