def animate_monotone_to_onion(points, u):
    path = monotone_path.monotone_path(points, u)

    #flip_sequence = switch.fixed_start_switch(points, path, 1)
    flip_sequence = switch.monotone_to_onion(points, path)

    path_sequence = flips_to_paths(path, flip_sequence, forget_orientation=False)

    animator.draw_polyline(DEFAULT_GRID, points, path_sequence[0], "svg-start-polyline.svg")
    animator.draw_polyline(DEFAULT_GRID, points, path_sequence[-1], "svg-target-polyline.svg")
    animator.create_gif_polyline(animator.DEFAULT_GRID, points, path_sequence, "Monotone switch")
 
